SELECT CAST((y2012.Consumption - y2013.Consumption) AS REAL) / y2012.Consumption
FROM (SELECT ym.Consumption FROM yearmonth ym JOIN transactions_1k t ON ym.CustomerID = t.CustomerID WHERE t.Date = '2012-08-25' AND t.Price = 634.8 AND ym.Date LIKE '2012%' LIMIT 1) AS y2012,
     (SELECT ym.Consumption FROM yearmonth ym JOIN transactions_1k t ON ym.CustomerID = t.CustomerID WHERE t.Date = '2012-08-25' AND t.Price = 634.8 AND ym.Date LIKE '2013%' LIMIT 1) AS y2013;
